const nCard=(p)=>{(window.PS=window.PS||{})[p.id]=p;const a=esc(p.author.replace(/_/g," ")),o=`onclick="leer(${p.id})" onkeydown="if(event.key==='Enter')leer(${p.id})" tabindex="0" role="button"`;return `<article class="nc" ${o}><div class="im"><em>${fecha(p.created_at)}</em></div><div class="bd"><h4>${esc(p.title)}</h4><p>${esc(exc(p.body))}</p><span class="rm">${a} · ${t("Leer más")} &gt;&gt;</span></div></article>`};
