function cerrarHoja(){const s=$("#sh");if(s){s.classList.remove("on");s.innerHTML=""}document.body.classList.remove("nosc");NP.f.forEach(x=>URL.revokeObjectURL(x.u));if(HS.u)URL.revokeObjectURL(HS.u);NP={f:[],tags:[]};HS={}}
