async function picBlob(f,max=1600){const bm=await createImageBitmap(f),k=Math.min(1,max/Math.max(bm.width,bm.height)),c=document.createElement("canvas");c.width=Math.round(bm.width*k);c.height=Math.round(bm.height*k);c.getContext("2d").drawImage(bm,0,0,c.width,c.height);let ql=.85,b;do{b=await new Promise(r=>c.toBlob(r,"image/jpeg",ql));ql-=.1}while(b&&b.size>1100000&&ql>.3);if(!b)throw 0;return b}
