function etDel(n){NP.tags=NP.tags.filter(x=>x!==n);etChips()}
// ---- Crear historia ----
function vidInfo(f){return new Promise((ok,no)=>{const v=document.createElement("video"),u=URL.createObjectURL(f),fin=x=>{URL.revokeObjectURL(u);clearTimeout(to);x?ok(x):no()},to=setTimeout(()=>fin(),8000);v.preload="auto";v.muted=true;v.playsInline=true;v.onerror=()=>fin();v.onloadedmetadata=()=>{v.currentTime=Math.min(.4,(v.duration||1)/3)};
 v.onseeked=()=>{try{const k=Math.min(1,480/Math.max(v.videoWidth,v.videoHeight)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(v.videoWidth*k));c.height=Math.max(1,Math.round(v.videoHeight*k));c.getContext("2d").drawImage(v,0,0,c.width,c.height);const d=v.duration;c.toBlob(b=>fin(b&&isFinite(d)?{dur:d,thumb:b}:null),"image/jpeg",.8)}catch{fin()}};v.src=u})}
function nuevaHist(){if(!U)return login();HS={};
 hoja(hdr("Crear historia",`<button class="btn p s" type="button" id="hsb" disabled onclick="pubHist()">${t("Compartir")}</button>`)+`<div class="shb"><input type="file" id="hsf" accept="image/*,video/mp4,video/quicktime,video/webm" hidden onchange="hsPick(this)"><button type="button" class="hs-p" id="hsp" onclick="$('#hsf').click()">${ic("galeria")}<b>${t("Elegir foto o video")}</b><small>${t("Foto o video de hasta 15 s")}</small></button><input id="hsc" maxlength="200" placeholder="${t("Añade un texto…")}" aria-label="${t("Añade un texto…")}" style="margin-top:.8rem"><div class="msg" id="hsm" role="alert"></div></div>`)}
async function hsPick(inp){const f=inp.files[0],m=$("#hsm");inp.value="";if(!f)return;m.className="msg";m.textContent="";const vid=/^video\//.test(f.type),mx=INFO.videoMax||25;
 if(!vid&&!/^image\//.test(f.type))return m.textContent=t("Elige una foto o un video");
 if(HS.u)URL.revokeObjectURL(HS.u);HS={};$("#hsb").disabled=true;
 if(vid){if(!/^video\/(mp4|quicktime|webm)$/.test(f.type))return m.textContent=t("Usa un video MP4");if(f.size>mx*1048576)return m.textContent=`${t("El video pesa demasiado")} (máx. ${mx} MB)`;
  m.textContent=t("Leyendo video…");let r;try{r=await vidInfo(f)}catch{r=null}m.textContent="";if(!r)return m.textContent=t("No pude leer ese video");if(!(r.dur>0)||r.dur>15.2)return m.textContent=t("El video dura más de 15 segundos");
  HS={f,kind:"vid",thumb:r.thumb,u:URL.createObjectURL(f)};$("#hsp").innerHTML=`<video src="${HS.u}" muted loop autoplay playsinline></video>`}
 else{HS={f,kind:"img",u:URL.createObjectURL(f)};$("#hsp").innerHTML=`<img src="${HS.u}" alt="">`}
 $("#hsp").classList.add("on");$("#hsb").disabled=false}
async function pubHist(){const b=$("#hsb"),m=$("#hsm"),er=r=>{m.textContent=r.d.error||"Error";b.disabled=false};b.disabled=true;m.className="msg";m.textContent=t("Subiendo…");let id;
 if(HS.kind==="img"){let bl;try{bl=await picBlob(HS.f,1440)}catch{m.textContent=t("No pude leer esa imagen");b.disabled=false;return}const r=await subir(bl,"img");if(!r.ok)return er(r);id=r.d.id}
 else{const th=await subir(HS.thumb,"img");if(!th.ok)return er(th);const r=await subir(HS.f,"vid",th.d.id);if(!r.ok)return er(r);id=r.d.id}
 const r=await api("/stories",{method:"POST",body:{media:id,body:$("#hsc").value}});if(!r.ok)return er(r);
 cerrarHoja();toast(t("Historia publicada"));PG=0;show()}
// ---- Franja de historias y visor ----
function seen(){try{return JSON.parse(localStorage.getItem("seen")||"{}")}catch{return{}}}
function markSeen(id){try{const s=seen();s[id]=1;const k=Object.keys(s);if(k.length>400)delete s[k[0]];localStorage.setItem("seen",JSON.stringify(s))}catch{}}
function grupos(l){const m={},sn=seen();l.filter(s=>s.media&&s.media.length).forEach(s=>{(m[s.author]=m[s.author]||{author:s.author,skin:s.skin,items:[]}).items.push(s)});return Object.values(m).map(g=>{g.items.sort((a,b)=>a.id-b.id);g.un=g.items.some(s=>!sn[s.id]);return g}).sort((a,b)=>b.un-a.un||b.items.at(-1).id-a.items.at(-1).id)}
function storyStrip(l){window.SGL=l;window.SG=grupos(l);return `<div class="fbs"><button type="button" class="c1" onclick="nuevaHist()">${skin(U.skin,U.name)}<i>+</i><b>${t("Crear historia")}</b></button>${SG.map((g,i)=>`<button type="button" onclick="verGrupo(${i})"><img class="f" loading="lazy" decoding="async" src="${mid(g.items.at(-1).media[0])}" alt=""><span class="fr${g.un?"":" sn"}">${skin(g.skin,g.author)}</span><b>${nom(g.author)}</b></button>`).join("")}</div>`}
function verGrupo(i){abrirVisor(SG[i])}
async function verHist(id){const p=PS[id];if(!p)return;const r=await api("/posts?type=story&author="+encodeURIComponent(p.author)),l=(r.ok?r.d:[]).filter(s=>s.media&&s.media.length).sort((a,b)=>a.id-b.id),i=l.findIndex(s=>s.id===id);if(i<0)return toast(t("Esta historia ya caducó"));abrirVisor({author:p.author,skin:p.skin,items:l},i,true)}
function abrirVisor(g,i,solo){if(V)svClose();if(i==null){const sn=seen();i=Math.max(0,g.items.findIndex(s=>!sn[s.id]))}
 V={g,i,solo,pz:false,t:0,last:0,v:null,raf:0,hold:0,held:false};document.body.classList.add("nosc");const d=document.createElement("div");d.id="sv";d.className="sv";
 d.innerHTML=`<div class="sv-w"><div class="sv-m" id="svm"></div><div class="sv-b" id="svb"></div><div class="sv-h" id="svh"></div><div class="sv-z l" onpointerdown="svDn()" onpointerup="svUp(-1)" onpointercancel="svRs()" onpointerleave="svRs()"></div><div class="sv-z r" onpointerdown="svDn()" onpointerup="svUp(1)" onpointercancel="svRs()" onpointerleave="svRs()"></div><div class="sv-a" id="sva"></div><div class="sv-c" id="svc"></div></div>`;document.body.appendChild(d);svShow(i);V.raf=requestAnimationFrame(svLoop)}
function svShow(i){const g=V.g,s=g.items[i],m=s.media[0];V.i=i;V.t=0;V.last=0;V.pz=false;V.v=null;markSeen(s.id);
 $("#svb").innerHTML=g.items.map((_,k)=>`<span id="sb${k}"><i style="width:${k<i?100:0}%"></i></span>`).join("");
 $("#svh").innerHTML=`${skin(g.skin,g.author)}<div><a href="${lk(g.author)}"><b>${nom(g.author)}</b></a><small>${ago(s.created_at)}</small></div><button type="button" class="x" onclick="svClose()" aria-label="${t("Cerrar")}">${ic("cerrar")}</button>`;
 if(m.kind==="vid"){$("#svm").innerHTML=`<video id="svv" src="/media/${m.id}" poster="/media/${m.thumb}" autoplay playsinline></video>`;const v=$("#svv");V.v=v;v.onended=()=>svGo(1);v.onerror=()=>svGo(1);v.play().catch(()=>{v.muted=true;v.play().catch(()=>{});svAct()})}
 else $("#svm").innerHTML=`<img src="/media/${m.id}" alt="">`;
 $("#svc").classList.remove("on");svAct()}
function svAct(){const s=V.g.items[V.i],own=U&&(U.name===s.author||U.canPost),vid=s.media[0].kind==="vid";
 $("#sva").innerHTML=`${s.body?`<p class="sv-cap">${esc(s.body)}</p>`:""}<div class="sv-ar"><button type="button" class="${s.mine>0?"p":""}" onclick="svLike()" aria-label="Like">${ic("like")} <span>${s.likes}</span></button><button type="button" onclick="svCom()" aria-label="${t("Comentarios")}">${ic("discord_comentarios")} <span>${s.comments}</span></button><button type="button" onclick="compartir(${s.id})" aria-label="${t("Compartir")}">${ic("compartir_vincular")}</button>${vid?`<button type="button" onclick="svMute()">${V.v&&V.v.muted?"🔇":"🔊"}</button>`:""}${own?`<button type="button" onclick="svDel()">${t("Eliminar")}</button>`:""}</div>`}
function svLoop(ts){if(!V)return;const dt=Math.min(100,V.last?ts-V.last:0);V.last=ts;let f=0;if(V.v)f=V.v.duration?V.v.currentTime/V.v.duration:0;else{if(!V.pz)V.t+=dt;f=Math.min(1,V.t/5000)}
 const b=document.querySelector("#sb"+V.i+" i");if(b)b.style.width=f*100+"%";if(!V.v&&f>=1){V.t=0;svGo(1)}if(V)V.raf=requestAnimationFrame(svLoop)}
function svPause(b){if(!V)return;V.pz=b;if(V.v){if(b)V.v.pause();else V.v.play().catch(()=>{})}}
function svDn(){V.held=false;clearTimeout(V.hold);V.hold=setTimeout(()=>{V.held=true;svPause(true)},220)}
function svUp(d){if(!V)return;clearTimeout(V.hold);if(V.held){V.held=false;svPause(false)}else svGo(d)}
function svRs(){if(!V)return;clearTimeout(V.hold);if(V.held){V.held=false;svPause(false)}}
function svGo(d){if(!V)return;const n=V.i+d;if(n<0)return svShow(0);if(n<V.g.items.length)return svShow(n);
 const gi=window.SG?SG.indexOf(V.g):-1;if(!V.solo&&gi>=0&&gi<SG.length-1){V.g=SG[gi+1];const sn=seen();svShow(Math.max(0,V.g.items.findIndex(s=>!sn[s.id])))}else svClose()}
function svClose(){if(!V)return;cancelAnimationFrame(V.raf);clearTimeout(V.hold);if(V.v)V.v.pause();V=null;$("#sv")?.remove();document.body.classList.remove("nosc");const st=$(".fbs");if(st&&window.SGL)st.outerHTML=storyStrip(SGL)}
function svMute(){if(V&&V.v){V.v.muted=!V.v.muted;svAct()}}
async function svLike(){if(!U){svPause(true);return login()}const s=V.g.items[V.i],r=await api("/posts/"+s.id+"/like",{method:"POST",body:{}});if(!r.ok||!V)return;s.mine=r.d.liked?1:0;s.likes=r.d.likes;svAct();const b=$("#l"+s.id);if(b){b.classList.toggle("p",r.d.liked);b.querySelector("span").textContent=r.d.likes}}
async function svCom(){const c=$("#svc");svPause(true);c.classList.add("on");c.innerHTML=`<div class="sv-ch"><b>${t("Comentarios")}</b><button type="button" class="x" onclick="svComX()" aria-label="${t("Cerrar")}">${ic("cerrar")}</button></div><div class="sv-cl" id="svcl"></div>${U?`<div class="sv-ci"><input id="svci" data-mn maxlength="300" placeholder="${t("Escribe un comentario…")}" aria-label="${t("Escribe un comentario…")}"><button class="btn p s" type="button" onclick="svSend()">${t("Enviar")}</button></div>`:`<div class="sv-ci"><button class="btn s" type="button" onclick="login()">${t("Inicia sesión para comentar")}</button></div>`}`;
 await svList();const i=$("#svci");if(i)i.onkeydown=e=>{if(e.key==="Enter")svSend()}}
function svComX(){$("#svc").classList.remove("on");svPause(false)}
async function svList(){if(!V)return;const s=V.g.items[V.i],r=await api("/posts/"+s.id+"/comments"),l=$("#svcl");if(!l)return;if(!r.ok)return l.innerHTML=`<p class="msg">${esc(r.d.error)}</p>`;s.comments=r.d.length;
 l.innerHTML=r.d.map(c=>`<div class="cmt"><a href="${lk(c.author)}" style="color:var(--rosa)"><b>${nom(c.author)}</b></a> <small>${ago(c.created_at)}</small>${c.del?` <button class="lk" onclick="svDelC(${c.id})">${t("borrar")}</button>`:""}<br>${linkM(c.body)}</div>`).join("")||`<small>${t("Sé el primero en comentar.")}</small>`;
 svAct();const cb=$("#cb"+s.id+" span");if(cb)cb.textContent=r.d.length}
async function svSend(){const i=$("#svci"),v=i.value.trim();if(!v)return;const r=await api("/posts/"+V.g.items[V.i].id+"/comments",{method:"POST",body:{body:v}});if(!r.ok)return toast(r.d.error||"Error");i.value="";svList()}
