const agoS=s=>{const m=(Date.now()-new Date(String(s).replace(" ","T")))/6e4;if(!(m>=0))return"";const en=L==="en";return m<60?Math.max(1,Math.floor(m))+" min":m<1440?Math.floor(m/60)+" h":m<10080?Math.floor(m/1440)+" d":m<525600?Math.floor(m/10080)+(en?" w":" sem"):Math.floor(m/525600)+(en?" y":" a")};
