async function perfilFB(name){
 const own=!!U&&U.name===name,a=await api("/user/"+encodeURIComponent(name));
 if(!a.ok){window.PTITLE=t("Jugador no encontrado");return `<div class="card"><h3>${t("Jugador no encontrado")}</h3><p class="m">${t("No existe ningún jugador con ese nombre.")}</p><a class="btn p" style="margin-top:.6rem" href="/">${t("Ir al inicio")}</a></div>`}
 const u=own?{...a.d,...U,rango:U.rango}:a.d,nm=nom(u.name),tab=["todo","reels","fotos","amigos","guardados"].includes(PTAB)&&(PTAB!=="guardados"||own)?PTAB:"todo";window.PTITLE=u.name.replace(/_/g," ");
 // Resumen: los datos de la cuenta (los privados solo en tu propio perfil)
 const row=(i,h,x)=>`<li${x?' class="pfx"'+(PSUM?"":" hidden"):""}>${ic(i)}<span>${h}</span></li>`,b=v=>`<b>${esc(v)}</b>`,on=Number(u.connected)>0;
 const rows=own?[["estrella",`${t("Nivel")} ${b(u.level)}`],["clasificacion",`${t("Reputación")} ${b(u.rep)}`],["reloj",`${t("Tiempo jugado")} ${b(horas(u.time_playing))}`],["dinero",`${t("Efectivo")} ${b(money(u.cash))}`],["banco",`${t("Banco")} ${b(money(u.bank_money))}`],["staff_equipo",`${t("Facción")} ${b(u.crew||t("Ninguna"))}`],["telefono",`${t("Teléfono")} ${b(u.phone_number||"—")}`],["esposas",`${t("Arrestos")} ${b(u.arrests_count??0)}`],["calendario",`${t("Se unió en")} ${b(u.reg_date?fecha(u.reg_date):"—")}`],["jugar",`${t("Última conexión")} ${on?b(t("En línea")):b(u.last_connection?fecha(u.last_connection):"—")}`],["discord_comentarios",u.discord?`${t("Discord vinculado")} <small class="m">(ID ${esc(u.discord.discord_id)})</small> <button class="lk" type="button" onclick="desv()">${t("Desvincular")}</button>`:`${t("Discord sin vincular")} · <a class="lk" href="/auth/discord">${t("Vincular")}</a>`]]
  :[["estrella",`${t("Nivel")} ${b(u.level)}`],["clasificacion",`${t("Reputación")} ${b(u.rep)}`],["reloj",`${t("Tiempo jugado")} ${b(horas(u.time_playing))}`],["like",`${t("Me gusta recibidos")} ${b(u.likes)}`],["calendario",`${t("Se unió en")} ${b(u.reg_date?fecha(u.reg_date):"—")}`],["jugar",`${t("Última conexión")} ${on?b(t("En línea")):b(u.last_connection?fecha(u.last_connection):"—")}`]];
 const sum=`<section class="pfsum"><div class="pfh"><h3>${t("Resumen")}</h3>${rows.length>5?`<button class="lk" id="pfsb" type="button" onclick="pfSum()">${t(PSUM?"Ver menos":"Ver todo")}</button>`:""}</div><ul>${rows.map((r,i)=>row(r[0],r[1],i>=5)).join("")}</ul><div class="msg" id="dm" role="status"></div></section>`;
 const fl=u.fl||[],q="u="+encodeURIComponent(u.name);
 const head=`<section class="pfp"><div class="pfc"></div><div class="pfa">${skin(u.skin,u.name,"xl")}${on?`<i class="pfon" title="${t("En línea")}"></i>`:""}</div>
 <h1 class="pfn">${nm}${Number(u.admin_level)>0&&RE[u.admin_level]?`<span class="pfv" title="${esc(t(u.rango))}">${RE[u.admin_level]}</span>`:""}</h1><p class="pfr">${esc(t(u.rango))}${Number(u.vip)>0?" · VIP":""}</p>
 <p class="pfs"><b>${cnt(u.friends)}</b> ${t("amigos")} · <b>${cnt(u.posts)}</b> ${t("publicaciones")} · <b>${cnt(u.reels)}</b> ${t("reels")}</p>
 ${fl.length?`<button class="pff" type="button" onclick="pfTab('amigos')"><span>${fl.slice(0,3).map(x=>skin(x.skin,x.name)).join("")}</span>${t("Amigos")}</button>`:""}
 ${own?`<div class="pfb"><button class="btn p" type="button" onclick="nuevaHist()">${ic("mas")} ${t("Agregar a historia")}</button><a class="btn" href="/reels?nuevo=1">${ic("videos")} ${t("Crear reel")}</a></div>`:U?`<div class="pfb fra" data-n="${esc(u.name)}" data-rl>${frActs(u.name,u.fstate)}</div>`:`<div class="pfb"><button class="btn p" type="button" onclick="login()">+ ${t("Agregar a amigos")}</button></div>`}
 <nav class="pft" aria-label="${t("Secciones")}">${[["todo","Todo"],["reels","Reels"],["fotos","Fotos"]].map(x=>`<button type="button"${tab===x[0]?' class="on" aria-current="true"':""} onclick="pfTab('${x[0]}')">${t(x[1])}</button>`).join("")}<button type="button"${tab==="amigos"||tab==="guardados"?' class="on"':""} onclick="pfMas(${own})">${t(tab==="amigos"?"Amigos":tab==="guardados"?"Guardados":"Más")} ▾</button></nav></section>`;
 let body="";
 if(tab==="todo"){const r=await api("/posts?type=post&author="+encodeURIComponent(u.name)+"&page="+PG),l=r.ok?r.d.slice(0,12):[],more=r.ok&&r.d.length>12;
  body=(PG?"":sum)+(own?composer():"")+(l.length?l.map(postHtml).join("")+(PG||more?pgn(more):""):`<div class="card m pfe">${t("Aún no hay publicaciones.")}</div>`)}
 else if(tab==="reels"){const r=await api("/reels?n=24&author="+encodeURIComponent(u.name)),l=r.ok?r.d.items:[];body=l.length||own?reelGrid(l,q,own):`<div class="card m pfe">${t("Aún no hay reels.")}</div>`}
 else if(tab==="guardados"){const r=await api("/reels?n=24&saved=1"),l=r.ok?r.d.items:[];body=l.length?reelGrid(l,"saved=1"):`<div class="card m pfe">${t("No has guardado ningún reel.")}</div>`}
 else if(tab==="fotos"){const r=await api("/user/"+encodeURIComponent(u.name)+"/photos"),l=r.ok?r.d:[];body=l.length?`<div class="pgd">${l.map(x=>`<button type="button" onclick="pfFoto(${x.id},${x.post_id})"><img loading="lazy" decoding="async" src="/media/${x.id}" alt=""></button>`).join("")}</div>`:`<div class="card m pfe">${t("Aún no hay fotos.")}</div>`}
 else body=fl.length?`<div class="card"><div class="fav">${fl.map(x=>`<a href="${lk(x.name)}">${skin(x.skin,x.name,"lg")}<span>${nom(x.name)}</span></a>`).join("")}</div></div>`:`<div class="card m pfe">${t("Aún no tienes amigos. Agrega a alguien de las sugerencias.")}</div>`;
 document.body.classList.add("pf-pg");
 return `<div class="pfw">${head}${body}</div>`}
function pfFoto(id,pid){modal(`<img src="/media/${id}" alt=""><div class="act" style="margin-top:.6rem"><a class="btn p" href="/p/${pid}">${t("Ver publicación")}</a><button class="btn" onclick="cerrar()">${t("Cerrar")}</button></div>`,1)}
async function desv(){if(confirm(t("¿Desvincular tu Discord?"))){await api("/discord",{method:"DELETE"});await init();show()}}
